import React from "react";
import { Link } from "react-router-dom";

export default function ListingCard({ listing }) {
  return (
    <div style={{
      border: "1px solid #ccc",
      borderRadius: "12px",
      width: "250px",
      padding: "10px",
      background: "white"
    }}>
      <img
        src={listing.images || "/placeholder.png"}
        alt={listing.title}
        style={{ width: "100%", borderRadius: "8px", height: "150px", objectFit: "cover" }}
      />
      <h3>{listing.title}</h3>
      <p>{listing.price} ₹</p>
      <p>{listing.location}</p>
      <Link to={`/edit-listing/${listing._id}`}><button>Edit</button></Link>
    </div>
  );
}
